use hec_native_ic::{fp::Fp,instance::{pick_instance,factor_base},jac::{Curve,Div},poly::Poly,oracle::{split,OracleStats}};
fn kernel(mut a:[[u64;4];3],f:&Fp)->(usize,[u64;4]){let mut r=0;let mut piv=vec![];for j in 0..4{let Some(i)=(r..3).find(|&i|a[i][j]!=0)else{continue};a.swap(r,i);let z=f.inv(a[r][j]);for k in j..4{a[r][k]=f.mul(a[r][k],z)}for i in 0..3{if i==r{continue}let z=a[i][j];for k in j..4{a[i][k]=f.sub(a[i][k],f.mul(z,a[r][k]))}}piv.push(j);r+=1;if r==3{break}}
if r!=3{return(4-r,[0;4])}let free=(0..4).find(|j|!piv.contains(j)).unwrap();let mut out=[0;4];out[free]=1;for(i,&j)in piv.iter().enumerate(){out[j]=f.neg(a[i][free]);} (1,out)}
fn construct(c:&Curve,d:&Div,ps:&[(u64,u64)])->(&'static str,Option<Div>){let f=&c.fp;if d.u.deg()!=c.g as isize||Poly::gcd(&d.u,&d.v,f).deg()!=0{return("input",None)}if ps.iter().any(|z|d.u.eval(z.0,f)==0){return("overlap",None)}let mut rows=[[0u64;4];3];for(i,&(x,y))in ps.iter().enumerate(){let e=f.sub(d.v.eval(x,f),y);let u=d.u.eval(x,f);rows[i]=[e,f.mul(x,e),u,f.mul(x,u)];}let(n,v)=kernel(rows,f);if n!=1{return("nullity",None)}for r in rows{let mut s=0;for j in 0..4{s=f.add(s,f.mul(r[j],v[j]));}assert_eq!(s,0)}let b=Poly::from_coeffs(&v[..2]);let cc=Poly::from_coeffs(&v[2..]);let a=d.v.mul(&b,f).add(&d.u.mul(&cc,f),f);if b.is_zero(){return("zero_B",None)}if Poly::gcd(&a,&b,f).deg()!=0{return("nonprimitive",None)}if Poly::gcd(&b,&d.u,f).deg()!=0{return("B_u_overlap",None)}if ps.iter().any(|z|b.eval(z.0,f)==0){return("anchor_denominator",None)}let mut den=d.u;for &(x,_)in ps{den=den.mul(&Poly::x_minus(x,f),f)}let norm=a.mul(&a,f).sub(&c.f.mul(&b.mul(&b,f),f),f);let(q,rem)=norm.divrem(&den,f);assert!(rem.is_zero());assert!(!q.is_zero());assert!(q.deg()<=c.g as isize);let q=q.monic(f);let(g,inv,_)=Poly::xgcd(&b,&q,f);assert_eq!(g,Poly::one());let e=Div{u:q,v:a.mulmod(&inv,&q,f)};assert!(c.is_valid(&e));("admitted",Some(e))}
fn main(){println!("g\tp\ttarget\ttriples\tclasses\tinput\toverlap\tnullity\tzero_B\tnonprimitive\tB_u_overlap\tanchor_denominator\tadmitted\tsplit\tnonsplit\tdegree_drop\trepeated_target\trepeated_admitted");for(g,p,h)in[(2,251,8usize),(3,211,9),(4,61,10)]{let inst=pick_instance(p,g).unwrap();let c=&inst.curve;let f=&c.fp;let fb=factor_base(c);for target in 0..2{let k=if target==0{inst.ell/7+19}else{inst.ell/11+29};let d=c.mul(&inst.d1,k);let repeated=Poly::gcd(&d.u,&d.u.deriv(f),f).deg()>0;let mut counts=[0u64;10];let(mut triples,mut classes,mut smooth,mut nonsplit,mut drops,mut repeated_admitted)=(0,0,0,0,0,0);let mut stats=OracleStats::default();'tuples:for i in 0..h{for j in i+1..h{for l in j+1..h{if triples==64{break 'tuples}triples+=1;for mask in 0..8{classes+=1;let ps:Vec<_>=[i,j,l].into_iter().enumerate().map(|(bit,z)|{let(x,y)=fb[z];(x,if mask&(1<<bit)!=0{f.neg(y)}else{y})}).collect();let(status,e)=construct(c,&d,&ps);let idx=match status{"input"=>0,"overlap"=>1,"nullity"=>2,"zero_B"=>3,"nonprimitive"=>4,"B_u_overlap"=>5,"anchor_denominator"=>6,"admitted"=>7,_=>panic!()};counts[idx]+=1;if let Some(e)=e{let mut direct=d;for &(x,y)in &ps{direct=c.add_place(&direct,x,y)}direct=c.neg(&direct);assert_eq!(e,direct,"exact reduced residual");let rs=split(&e.u,f,&mut stats);assert_eq!(rs.is_some(),split(&direct.u,f,&mut stats).is_some());if let Some(rs)=rs{smooth+=1;let mut sum=d;for &(x,y)in &ps{sum=c.add_place(&sum,x,y)}for &(x,m)in rs.as_slice(){let y=e.v.eval(x,f);sum=c.add(&sum,&c.mul(&c.place(x,y),m as u64));}assert!(c.is_zero(&sum));}else{nonsplit+=1}drops+=u64::from(e.u.deg()<g as isize);repeated_admitted+=u64::from(repeated);}}}}}
println!("{g}\t{p}\t{target}\t{triples}\t{classes}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{smooth}\t{nonsplit}\t{drops}\t{repeated}\t{repeated_admitted}",counts[0],counts[1],counts[2],counts[3],counts[4],counts[5],counts[6],counts[7]);}}}
